def soperator_migration_checkpoint_path(
    config_path: Path,
    target_ref: str,
    **kwargs: Any,
) -> Path:
    kwargs.setdefault("payload_or_config", _payload())
    return _soperator_migration_checkpoint_path(config_path, target_ref, **kwargs)


def _external_upgrade_report_dir(
    project_dir: Path,
    *,
    payload: Mapping[str, Any] | None = None,
) -> Path:
    active_payload = _payload() if payload is None else payload
    identity = soperator_cluster_artifact_identity_from_payload(
        active_payload,
        target_ref="external-cluster",
    )
    return (
        project_dir
        / "generated"
        / "reports"
        / "soperator-clusters"
        / identity.cluster_key
        / "ext-soperator-upgrade"
    )


def _external_upgrade_report_path(
    project_dir: Path,
    *,
    payload: Mapping[str, Any] | None = None,
) -> Path:
    return _external_upgrade_report_dir(project_dir, payload=payload) / "report.md"


def _external_upgrade_report_json_path(
    project_dir: Path,
    *,
    payload: Mapping[str, Any] | None = None,
) -> Path:
    return _external_upgrade_report_dir(project_dir, payload=payload) / "report.json"


@pytest.mark.parametrize(
    ("preexisting", "expected_action"),
    [(True, "reused"), (False, "created")],
)
def test_passive_populate_job_uid_is_checkpointed_before_ensure_returns(
    preexisting: bool,
    expected_action: str,
) -> None:
    pvc_name = "jail-rootfs-slot-b-pvc"
    pvc_uid = f"pvc-uid-{pvc_name}"
    image = "registry.example/populate-jail:test"
    manifest = migration.active_passive_populate_jail_job_manifest(
        namespace="soperator",
        target_ref="external-cluster",
        image=image,
        passive_slot="slot-b",
        passive_pvc=pvc_name,
        image_pull_policy="IfNotPresent",
        scheduling={},
    )
    state = migration._bind_passive_populate_job_checkpoint(  # noqa: SLF001
        existing={},
        manifest=manifest,
        slot="slot-b",
        pvc=pvc_name,
        image=image,
    )
    state["pvc_uid"] = pvc_uid
    job_name = str(state["name"])
    live_job = copy.deepcopy(manifest)
    live_job.setdefault("metadata", {})["uid"] = "passive-job-uid"
    runner = _FakeCommandRunner(live_pvcs=[_bound_pvc(pvc_name)])
    if preexisting:
        runner.live_jobs[("soperator", job_name)] = live_job
    checkpointed_uids: list[str] = []

    action = migration._ensure_passive_populate_job(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        namespace="soperator",
        manifest=manifest,
        expected_pvc_uid=pvc_uid,
        state=state,
        checkpoint_writer=lambda: checkpointed_uids.append(str(state.get("uid") or "")),
    )

    expected_uid = "passive-job-uid" if preexisting else f"job-uid-{job_name}"
    assert action == expected_action
    assert checkpointed_uids == [expected_uid]
    assert state["uid"] == expected_uid


