    monkeypatch.setattr(migration.time, "sleep", lambda _seconds: None)

    result = migration._default_command_runner(  # noqa: SLF001
        ["kubectl", "get", "pods"],
        check=False,
    )

    assert result.returncode == 0
    assert result.stdout == "ok"
    assert len(calls) == 2


