def _install_executor_bridge_worker_lifecycle_fixture(
    monkeypatch: pytest.MonkeyPatch,
    *,
    snapshot: dict[str, Any],
    stage_trace: list[str] | None = None,
    runner: _FakeCommandRunner | None = None,
    add_default_worker: bool = True,
    target_worker_nodesets: Sequence[str] = ("worker",),
) -> _FakeCommandRunner:
    if add_default_worker:
        resources = snapshot.get("soperator_resources")
        assert isinstance(resources, list)
        resources.append(
            {
                "apiVersion": "slurm.nebius.ai/v1alpha1",
                "kind": "NodeSet",
                "metadata": {"name": "worker", "namespace": "soperator"},
                "spec": {
                    "replicas": 2,
                    "nodeSelector": {
                        "nebius.com/node-group-id": "nodegroup-gpu-pool",
                    },
                },
                "status": {
                    "phase": "Ready",
                    "replicas": 2,
                    "readyReplicas": 2,
                    "conditions": [{"type": "PodsReady", "status": "True"}],
                },
            }
        )
        source_worker = _legacy_service_node_group("worker", fixed_node_count=2)
        source_worker["metadata"].update({"id": "nodegroup-gpu-pool", "name": "gpu-pool"})
        live_nodes = [
            {
                "metadata": {
                    "name": name,
                    "uid": f"{name}-uid",
                    "labels": {
                        "nebius.com/node-group": group_name,
                        "nebius.com/node-group-id": group_id,
                        **(
                            {"slurm.nebius.ai/nodeset": "worker"}
                            if group_name.startswith("external-cluster-")
                            else {}
                        ),
                    },
                },
                "spec": {},
                "status": {"conditions": [{"type": "Ready", "status": "True"}]},
            }
            for name, group_name, group_id in (
                ("node-a", "gpu-pool", "nodegroup-gpu-pool"),
                ("node-b", "gpu-pool", "nodegroup-gpu-pool"),
                (
                    "target-node-a",
                    "external-cluster-gpu-pool",
                    "nodegroup-external-cluster-gpu-pool",
                ),
                (
                    "target-node-b",
                    "external-cluster-gpu-pool",
                    "nodegroup-external-cluster-gpu-pool",
                ),
            )
        ]
        if runner is None:
            runner = _FakeCommandRunner(
                existing_node_groups=[source_worker],
                live_nodes=live_nodes,
            )
        else:
            runner.existing_node_groups.append(source_worker)
            runner.live_nodes.extend(live_nodes)
    elif runner is None:
        raise AssertionError("runner is required when add_default_worker is false")
    assert runner is not None
    _install_controller_bridge_lifecycle_fixture(
        monkeypatch,
        stage_trace=stage_trace if stage_trace is not None else [],
        target_snapshot=snapshot,
    )
    monkeypatch.setattr(
        migration,
        "_run_soperator_migration_quota_preflight",
        lambda **_kwargs: ["Quota preflight fixture satisfied."],
    )
    monkeypatch.setattr(
        migration,
        "_verify_target_jail_alias_consumers",
        lambda **_kwargs: [{"kind": "StatefulSet", "name": "login", "status": "verified"}],
    )
    monkeypatch.setattr(
        migration,
        "_wait_for_target_worker_nodesets_ready",
        lambda **_kwargs: {
            name: {
                "nodeset_uid": f"target-nodeset-uid-{name}",
                "workload_uid": f"advancedstatefulset-uid-{name}",
                "configured_replicas": "1",
            }
            for name in target_worker_nodesets
        },
    )
    monkeypatch.setattr(
        migration,
        "_ensure_final_slurm_worker_runtime_identity",
        lambda **_kwargs: {
            "schema": "nebius-cxcli/final-slurm-worker-runtime-identity-v1",
            "status": "verified",
            "worker_count": 2,
        },
    )
    return runner


def execute_soperator_migration(*args: Any, **kwargs: Any):
    payload = kwargs.get("payload")
    source_report = kwargs.get("source_report")
    if (
        "campaign" not in kwargs
        and isinstance(payload, dict)
        and isinstance(source_report, Mapping)
    ):
        campaign = _project_campaign_node_group_targets(payload, source_report)
        kwargs["campaign"] = campaign
        kwargs["campaign_fingerprint"] = campaign["fingerprint"]
        kwargs["campaign_segment_id"] = campaign["segments"][0]["id"]
    else:
        for key, value in _campaign_execution_kwargs().items():
            kwargs.setdefault(key, value)
    if kwargs.get("approved") is True:
        raw_config_path = kwargs.get("config_path") if "config_path" in kwargs else args[0]
        config_path = Path(raw_config_path)
        if "backup_metadata" in kwargs:
            kwargs["backup_metadata"] = _backup_metadata_with_existing_archive(
                config_path,
                kwargs["backup_metadata"],
            )
        else:
            existing_backup = migration.external_soperator_upgrade_resume_backup_metadata(
                config_path,
                str(kwargs.get("target_ref") or "external-cluster"),
                payload_or_config=payload,
            )
            kwargs["backup_metadata"] = existing_backup or _backup_metadata_with_archive(
                config_path,
                "test-pre-upgrade",
            )
    if kwargs.get("nebius_api") is None and kwargs.get("command_runner") is None:
        kwargs["command_runner"] = _FakeCommandRunner()
    if isinstance(source_report, Mapping):
        accepted_snapshot = copy.deepcopy(dict(source_report.get("snapshot") or {}))
        kwargs.setdefault(
            "source_identity_collector",
            lambda *, kube_context: accepted_snapshot,
        )
    return _execute_soperator_migration(*args, **kwargs)


_STALE_KUBE_RBAC_PROXY_REPOSITORY = "gcr.io/kubebuilder/kube-rbac-proxy"
_TARGET_KUBE_RBAC_PROXY_REPOSITORY = "registry.k8s.io/kubebuilder/kube-rbac-proxy"
_TARGET_KUBE_RBAC_PROXY_TAG = "v0.15.0"


def _target_soperator_chart_values(payload: dict[str, Any]) -> dict[str, Any]:
    charts = payload["apps"]["charts"]  # type: ignore[index]
    assert isinstance(charts, list)
    values = charts[0]["values"]
    assert isinstance(values, dict)
    return values


def _seed_stale_kube_rbac_proxy_values(payload: dict[str, Any]) -> None:
    values = _target_soperator_chart_values(payload)
    values["controllerManager"] = {
        "kubeRbacProxy": {
            "image": {
                "repository": _STALE_KUBE_RBAC_PROXY_REPOSITORY,
                "tag": _TARGET_KUBE_RBAC_PROXY_TAG,
                "pullPolicy": "Always",
            }
        }
    }
    values["soperator-checks"] = {
        "checks": {
            "kubeRbacProxy": {
                "image": {
                    "repository": _STALE_KUBE_RBAC_PROXY_REPOSITORY,
                    "tag": _TARGET_KUBE_RBAC_PROXY_TAG,
                    "pullPolicy": "IfNotPresent",
                }
            }
        }
    }


def _assert_target_kube_rbac_proxy_values(helm_values: dict[str, Any]) -> None:
    controller_image = helm_values["controllerManager"]["kubeRbacProxy"]["image"]
    assert controller_image["repository"] == _TARGET_KUBE_RBAC_PROXY_REPOSITORY
    assert controller_image["tag"] == _TARGET_KUBE_RBAC_PROXY_TAG
    assert controller_image["pullPolicy"] == "Always"

    checks_image = helm_values["soperator-checks"]["checks"]["kubeRbacProxy"]["image"]
    assert checks_image["repository"] == _TARGET_KUBE_RBAC_PROXY_REPOSITORY
    assert checks_image["tag"] == _TARGET_KUBE_RBAC_PROXY_TAG
    assert checks_image["pullPolicy"] == "IfNotPresent"


def test_patch_target_kube_rbac_proxy_images_repairs_missing_or_malformed_paths() -> None:
    values: dict[str, Any] = {
        "controllerManager": {"kubeRbacProxy": {"image": "stale"}},
        "soperator-checks": "stale",
    }

    migration._patch_target_kube_rbac_proxy_images(values)  # noqa: SLF001

    assert values["controllerManager"]["kubeRbacProxy"]["image"] == {
        "repository": _TARGET_KUBE_RBAC_PROXY_REPOSITORY,
        "tag": _TARGET_KUBE_RBAC_PROXY_TAG,
    }
    assert values["soperator-checks"]["checks"]["kubeRbacProxy"]["image"] == {
        "repository": _TARGET_KUBE_RBAC_PROXY_REPOSITORY,
        "tag": _TARGET_KUBE_RBAC_PROXY_TAG,
    }


