    original = migration._checkpoint_source_cleanup_started  # noqa: SLF001
    cleanup_intent_seen = False

    def checkpoint_then_drift_source_command(**kwargs: Any) -> None:
        nonlocal cleanup_intent_seen
        original(**kwargs)
        cleanup_intent_seen = True
