@pytest.mark.parametrize(
    ("failing_pod", "replacement_on_final_reread", "mixed_driver_contract"),
    [
        pytest.param(None, False, False, id="passed"),
        pytest.param("worker-1", False, False, id="runtime-probe-failed"),
        pytest.param(None, True, False, id="uid-drift-final-reread"),
        pytest.param(None, False, True, id="mixed-driver-contract"),
    ],
)
def test_gpu_workload_release_gate_precedes_partition_restore(
    monkeypatch: pytest.MonkeyPatch,
    failing_pod: str | None,
    replacement_on_final_reread: bool,
    mixed_driver_contract: bool,
) -> None:
    events: list[str] = []

    def worker_pod(index: int) -> dict[str, Any]:
        name = f"worker-{index}"
        slurmd_image = "registry.example/soperator/slurmd:target"
        return {
            "metadata": {
                "name": name,
                "namespace": "soperator",
                "uid": f"pod-uid-{name}",
                "labels": {"slurm.nebius.ai/nodeset-name": "worker"},
                "ownerReferences": [
                    {
                        "apiVersion": "apps.kruise.io/v1beta1",
                        "kind": "StatefulSet",
                        "name": "worker",
                        "uid": "advancedstatefulset-uid-worker",
                        "controller": True,
                    }
                ],
            },
            "spec": {
                "nodeName": f"gpu-node-{index}",
                "containers": [
                    {
                        "name": "slurmd",
                        "image": slurmd_image,
                        "volumeMounts": [
                            {
                                "name": migration.SOPERATOR_GPU_DRIVER_JAIL_MOUNT_NAME,
                                "mountPath": migration.SOPERATOR_GPU_DRIVER_JAIL_MOUNT_PATH,
                                "readOnly": True,
                            },
                            {
                                "name": migration._GPU_HEALTH_SYSFS_MOUNT_NAME,  # noqa: SLF001
                                "mountPath": migration._GPU_HEALTH_SYSFS_MOUNT_PATH,  # noqa: SLF001
                                "readOnly": True,
                            },
                        ],
                    }
                ],
                "initContainers": [
                    {
                        "name": migration.SOPERATOR_GPU_DRIVER_JAIL_INIT_CONTAINER_NAME,
                        "image": slurmd_image,
                        "command": ["/bin/bash", "-c"],
                        "args": [
                            "\n".join(migration._GPU_DRIVER_JAIL_CANONICAL_SCRIPT_LINES)  # noqa: SLF001
                        ],
                        # The Kubernetes API serializes resource quantities as strings.
                        "resources": {"limits": {"nvidia.com/gpu": "1"}},
                        "securityContext": {
                            "allowPrivilegeEscalation": False,
                            "readOnlyRootFilesystem": True,
                            "runAsNonRoot": False,
                            "runAsUser": 0,
                            "capabilities": {
                                "drop": ["ALL"],
                                "add": ["SYS_CHROOT"],
                            },
                        },
                        "volumeMounts": [
                            {
                                "name": "jail",
                                "mountPath": "/mnt/jail",
                                "readOnly": True,
                            },
                            {
                                "name": migration.SOPERATOR_GPU_DRIVER_JAIL_MOUNT_NAME,
                                "mountPath": migration.SOPERATOR_GPU_DRIVER_JAIL_MOUNT_PATH,
                                "readOnly": True,
                            },
                            {
                                "name": "kube-api-access-abcde",
                                "mountPath": ("/var/run/secrets/kubernetes.io/serviceaccount"),
                                "readOnly": True,
                            },
                        ],
                    }
                ],
                "volumes": [
                    {"name": "jail", "persistentVolumeClaim": {"claimName": "jail-pvc"}},
                    {
                        "name": migration.SOPERATOR_GPU_DRIVER_JAIL_MOUNT_NAME,
                        "hostPath": {"path": migration.SOPERATOR_GPU_DRIVER_JAIL_HOST_PATH},
                    },
                    {
                        "name": migration._GPU_HEALTH_SYSFS_MOUNT_NAME,  # noqa: SLF001
                        "hostPath": {
                            "path": migration._GPU_HEALTH_SYSFS_HOST_PATH,  # noqa: SLF001
                            "type": "Directory",
                        },
                    },
                    {
                        "name": "kube-api-access-abcde",
                        "projected": {
                            "defaultMode": 420,
                            "sources": [
                                {"serviceAccountToken": {}},
                                {"configMap": {}},
                                {"downwardAPI": {}},
                            ],
                        },
                    },
                ],
            },
            "status": {
                "phase": "Running",
                "conditions": [{"type": "Ready", "status": "True"}],
                "initContainerStatuses": [
                    {
                        "name": migration.SOPERATOR_GPU_DRIVER_JAIL_INIT_CONTAINER_NAME,
                        "state": {"terminated": {"exitCode": 0}},
                    }
                ],
            },
        }

    class GateRunner(_FakeCommandRunner):
        def __call__(self, args: Sequence[str], **kwargs: Any) -> Any:
            command = tuple(str(item) for item in args)
            if (
                "exec" in command
                and "slurmd" in command
                and migration._GPU_WORKLOAD_RELEASE_PROBE in command  # noqa: SLF001
            ):
                pod_name = command[command.index("exec") + 1]
                events.append(f"probe:{pod_name}")
                if pod_name == failing_pod:
                    return migration.SoperatorMigrationCommandResult(
                        command,
                        1,
                        "",
                        "gpu-workload-release-gate: libnvidia-ml.so.1 is missing",
                    )
                return migration.SoperatorMigrationCommandResult(
                    command,
                    0,
                    (
                        "gpu_count=8 driver_version="
                        + (
                            "555.42.02"
                            if mixed_driver_contract and pod_name == "worker-1"
                            else "550.90.07"
                        )
                        + " libcuda_sha256="
                        + "a" * 64
                        + " libnvidia_ml_sha256="
                        + "b" * 64
                        + "\n"
                    ),
                    "",
                )
            if command[5:7] == ("get", "pod") and command[7].startswith("worker-"):
                pod_name = command[7]
                pod = copy.deepcopy(
                    next(
                        item
                        for item in self.live_pods
                        if item.get("metadata", {}).get("name") == pod_name
                    )
                )
                if replacement_on_final_reread and pod_name == "worker-1":
                    pod["metadata"]["uid"] = "replacement-pod-uid-worker-1"
                return migration.SoperatorMigrationCommandResult(
                    command,
                    0,
                    json.dumps(pod),
                    "",
                )
            return super().__call__(args, **kwargs)

    runner = GateRunner(
        live_pods=[worker_pod(0), worker_pod(1)],
        live_nodesets={
            "worker": {
                "metadata": {"name": "worker", "namespace": "soperator"},
                "spec": {"replicas": 2},
                "status": {
                    "phase": "Ready",
                    "readyReplicas": 2,
                    "conditions": [{"type": "PodsReady", "status": "True"}],
                },
            }
        },
    )
    monkeypatch.setattr(
        migration,
        "_reconcile_slurm_worker_runtime_identity",
        lambda **_kwargs: [],
    )
    monkeypatch.setattr(
        migration,
        "_restore_external_upgrade_slurm_partitions",
        lambda **_kwargs: events.append("restore"),
    )
    phase: dict[str, Any] = {}
    values = {
        "nodesets": [
            {
                "name": "worker",
                "replicas": 2,
                "gpu": {"enabled": True},
            }
        ]
    }

    if failing_pod is None and not replacement_on_final_reread and not mixed_driver_contract:
        lines = migration._resume_slurm_after_cutover(  # noqa: SLF001
            command_runner=runner,
            kube_context="external-context",
            target_ref="external-cluster",
            phase=phase,
            values=values,
            checkpoint_writer=lambda: None,
            slurm_pause_records=(_slurm_partition_pause_record_fixture("main"),),
        )

        assert events == ["probe:worker-0", "probe:worker-1"]
        assert phase["gpu_workload_release_gate"]["status"] == "passed"
        assert "remain paused" in "\n".join(lines)
    else:
        failure_pattern = (
            "changed identity, readiness, ownership, or driver-jail contract"
            if replacement_on_final_reread
            else "mixed NVIDIA driver versions"
            if mixed_driver_contract
            else "libnvidia-ml.so.1 is missing"
        )
        with pytest.raises(
            migration.SoperatorMigrationPhasePending,
            match=failure_pattern,
        ):
            migration._resume_slurm_after_cutover(  # noqa: SLF001
                command_runner=runner,
                kube_context="external-context",
                target_ref="external-cluster",
                phase=phase,
                values=values,
                checkpoint_writer=lambda: None,
                slurm_pause_records=(_slurm_partition_pause_record_fixture("main"),),
            )

        assert "restore" not in events
        assert phase["gpu_workload_release_gate"]["status"] == "failed"
        if replacement_on_final_reread:
            failed_worker = phase["gpu_workload_release_gate"]["workers"][-1]
            assert failed_worker["pod_uid"] == "pod-uid-worker-1"
            assert failed_worker["observed_pod_uid"] == "replacement-pod-uid-worker-1"


class _TimeoutAfterAcceptedControlPlaneUpdateRunner(_FakeCommandRunner):
    def __init__(self) -> None:
        super().__init__(
            cluster={
                "metadata": {
                    "id": "cluster-123",
                    "name": "external-cluster",
                    "resource_version": 17,
                },
                "spec": {"control_plane": {"version": "1.31"}},
                "status": {
                    "state": "RUNNING",
                    "control_plane": {"version": "1.31"},
                },
            }
        )
        self.timed_out = False

    def __call__(
        self,
        args,
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorMigrationCommandResult:
        command = tuple(str(item) for item in args)
        if command[:4] == ("nebius", "mk8s", "cluster", "update") and not self.timed_out:
            super().__call__(
                command,
                input_text=input_text,
                timeout_seconds=timeout_seconds,
                check=check,
            )
            target_version = command[command.index("--control-plane-version") + 1]
            self.cluster["status"] = {
                "state": "PROVISIONING",
                "reconciling": True,
                "control_plane": {"version": target_version},
            }
            self.timed_out = True
            raise subprocess.TimeoutExpired(list(command), timeout_seconds)
        return super().__call__(
            command,
            input_text=input_text,
            timeout_seconds=timeout_seconds,
            check=check,
        )


def test_execute_external_node_template_stays_attached_after_accepted_timeout(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    source_report = _source_report()
    payload = _external_node_template_only_payload()
    runner = _TimeoutAfterAcceptedControlPlaneUpdateRunner()
    checkpoint: dict[str, Any] = {
        **_journal_contract_fields(),
        "controller_bridge": {
            "login_session_handoff": {
                "revision": 1,
                "state": "uninitialized",
                "locked_at": "",
                "source_services": [],
                "protected_pods": [],
                "sessions": [],
                "no_sessions_at_lock": False,
                "target_ready": False,
                "target_pod": {},
                "service_switched_at": "",
                "voluntary_handoff_at": "",
                "indeterminate_reason": "",
            }
        },
        "phase_state": {},
    }
    monkeypatch.setattr(
        migration,
        "_revalidate_protected_login_sessions",
        lambda **_kwargs: [],
    )
    original_get_provider_operation = runner.nebius_api.get_provider_operation

    def terminal_operation(*, operation_id: str, operation_kind: str):
        runner.cluster["status"] = {
            "state": "RUNNING",
            "reconciling": False,
            "control_plane": {"version": "1.32"},
        }
        return original_get_provider_operation(
            operation_id=operation_id,
            operation_kind=operation_kind,
        )

    monkeypatch.setattr(runner.nebius_api, "get_provider_operation", terminal_operation)
    mutation, lines = migration._execute_external_node_template_upgrade_phase(  # noqa: SLF001
        checkpoint=checkpoint,
        payload=payload,
        source_report=source_report,
        target_ref="external-cluster",
        kube_context="external-context",
        nebius_api=runner.nebius_api,
        command_runner=runner,
        checkpoint_writer=lambda: None,
    )

    assert mutation is True
    control_plane_updates = [
        call[0] for call in runner.calls if call[0][:4] == ("nebius", "mk8s", "cluster", "update")
    ]
    assert len(control_plane_updates) == 1
    assert not any(
        call[0][:4] == ("nebius", "mk8s", "node-group", "update") and "--version" in call[0]
        for call in runner.calls
    )
    phase = checkpoint["phase_state"]["external-node-template-upgrade"]
    assert phase["status"] == "completed"
    assert phase["node_group_mode"] == "blue-green"
    hop = phase["control_plane"]["hops"]["1.32"]
    assert hop["status"] == "completed"
    assert hop["operation"]["attempt_state"] == "provider-terminal"
    assert phase["source_node_groups"] == "retained"
    assert phase["target_node_group_owner"] == "rolling-compute-migration"
    assert hop["status"] == "completed"
    assert hop["operation"]["attempt_state"] == "provider-terminal"
    assert any("accepted blue-green replacements" in line for line in lines)


def test_execute_external_node_template_resume_waits_for_interrupted_control_plane(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    config_path = tmp_path / "config.yaml"
    source_report = _source_report()
    payload = _external_node_template_only_payload()
    checkpoint_path = _write_external_node_template_resume_checkpoint(
        config_path=config_path,
        payload=payload,
        source_report=source_report,
        phase_state={
            "control_plane": {
                "hops": {
                    "1.32": {
                        "status": "updating",
                        "from_version": "1.31",
                        "target_version": "1.32",
                        "provider_update_attempted": True,
                    }
                }
            }
        },
    )
    _attach_pending_control_plane_operation(checkpoint_path, target_version="1.32")
    runner = _FakeCommandRunner()
    checkpoint = json.loads(checkpoint_path.read_text(encoding="utf-8"))
    monkeypatch.setattr(
        migration,
        "_revalidate_protected_login_sessions",
        lambda **_kwargs: [],
    )

    with pytest.raises(
        migration.SoperatorMigrationPhasePending,
        match="terminal-successful.*exact live postcondition is not yet visible",
    ):
        migration._execute_external_node_template_upgrade_phase(  # noqa: SLF001
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            target_ref="external-cluster",
            kube_context="external-context",
            nebius_api=runner.nebius_api,
            command_runner=runner,
            checkpoint_writer=lambda: None,
        )

    cluster_updates = [
        call[0] for call in runner.calls if call[0][:4] == ("nebius", "mk8s", "cluster", "update")
    ]
    assert cluster_updates == []
    hop = checkpoint["phase_state"]["external-node-template-upgrade"]["control_plane"]["hops"][
        "1.32"
    ]
    assert hop["status"] == "updating"
    assert hop["reconciliation_status"] == "waiting"
    assert hop["reconciliation_reason"] == hop["pending_reason"]
    assert "will not submit a duplicate control-plane update" in hop["pending_reason"]


def test_control_plane_resume_rejects_terminal_failed_operation_before_live_target(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    config_path = tmp_path / "config.yaml"
    source_report = _source_report()
    payload = _external_node_template_only_payload()
    checkpoint_path = _write_external_node_template_resume_checkpoint(
        config_path=config_path,
        payload=payload,
        source_report=source_report,
        phase_state={
            "control_plane": {
                "hops": {
                    "1.32": {
                        "status": "updating",
                        "from_version": "1.31",
                        "target_version": "1.32",
                        "provider_update_attempted": True,
                    }
                }
            }
        },
    )
    operation_id = _attach_pending_control_plane_operation(
        checkpoint_path,
        target_version="1.32",
    )
    runner = _FakeCommandRunner(
        provider_operation_observations={
            operation_id: migration.SoperatorProviderOperationObservation(
                operation_id=operation_id,
                resource_id="cluster-123",
                terminal=True,
                successful=False,
                status="FAILED",
            )
        }
    )
    checkpoint = json.loads(checkpoint_path.read_text(encoding="utf-8"))
    monkeypatch.setattr(
        migration,
        "_revalidate_protected_login_sessions",
        lambda **_kwargs: [],
    )

    with pytest.raises(RuntimeError, match="non-success terminal status"):
        migration._execute_external_node_template_upgrade_phase(  # noqa: SLF001
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            target_ref="external-cluster",
            kube_context="external-context",
            nebius_api=runner.nebius_api,
            command_runner=runner,
            checkpoint_writer=lambda: None,
        )

    assert ("operation.get", operation_id) in runner.nebius_api.calls
    assert not any(call[0][:4] == ("nebius", "mk8s", "cluster", "update") for call in runner.calls)


def test_control_plane_resume_waits_for_provider_terminal_state_before_node_groups(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    config_path = tmp_path / "config.yaml"
    source_report = _source_report()
    payload = _external_node_template_only_payload()
    checkpoint_path = _write_external_node_template_resume_checkpoint(
        config_path=config_path,
        payload=payload,
        source_report=source_report,
        phase_state={
            "control_plane": {
                "hops": {
                    "1.32": {
                        "status": "updating",
                        "from_version": "1.31",
                        "target_version": "1.32",
                        "provider_update_attempted": True,
                    }
                }
            }
        },
    )
    operation_id = _attach_pending_control_plane_operation(
        checkpoint_path,
        target_version="1.32",
    )
    runner = _FakeCommandRunner(
        cluster={
            "metadata": {
                "id": "cluster-123",
                "name": "external-cluster",
                "resource_version": 17,
            },
            "spec": {"control_plane": {"version": "1.32"}},
            "status": {
                "state": "PROVISIONING",
                "reconciling": True,
                "control_plane": {"version": "1.32"},
            },
        }
    )
    checkpoint = json.loads(checkpoint_path.read_text(encoding="utf-8"))
    monkeypatch.setattr(
        migration,
        "_revalidate_protected_login_sessions",
        lambda **_kwargs: [],
    )

    with pytest.raises(
        migration.SoperatorMigrationPhasePending,
        match="not terminal-ready|exact live postcondition is not yet visible",
    ):
        migration._execute_external_node_template_upgrade_phase(  # noqa: SLF001
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            target_ref="external-cluster",
            kube_context="external-context",
            nebius_api=runner.nebius_api,
            command_runner=runner,
            checkpoint_writer=lambda: None,
        )

    assert not any(
        call[0][:4] == ("nebius", "mk8s", "node-group", "update") for call in runner.calls
    )
    assert not any(call[0][:4] == ("nebius", "mk8s", "cluster", "update") for call in runner.calls)
    hop = checkpoint["phase_state"]["external-node-template-upgrade"]["control_plane"]["hops"][
        "1.32"
    ]
    assert hop["status"] == "updating"
    assert hop["reconciliation_status"] == "waiting"
    assert hop["operation"]["attempt_state"] == "provider-pending"
    assert hop["operation"]["provider_operation_id"] == operation_id

    runner.cluster["status"] = {
        "state": "RUNNING",
        "reconciling": False,
        "control_plane": {"version": "1.32"},
    }
    migration._execute_external_node_template_upgrade_phase(  # noqa: SLF001
        checkpoint=checkpoint,
        payload=payload,
        source_report=source_report,
        target_ref="external-cluster",
        kube_context="external-context",
        nebius_api=runner.nebius_api,
        command_runner=runner,
        checkpoint_writer=lambda: None,
    )

    hop = checkpoint["phase_state"]["external-node-template-upgrade"]["control_plane"]["hops"][
        "1.32"
    ]
    assert hop["status"] == "completed"
    assert hop["reconciliation_status"] == "completed"
    assert hop["operation"]["attempt_state"] == "provider-terminal"
    assert hop["operation"]["provider_operation_id"] == operation_id
    assert not any(call[0][:4] == ("nebius", "mk8s", "cluster", "update") for call in runner.calls)


def test_control_plane_resume_rejects_provider_operation_identity_mismatch(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    config_path = tmp_path / "config.yaml"
    source_report = _source_report()
    payload = _external_node_template_only_payload()
    checkpoint_path = _write_external_node_template_resume_checkpoint(
        config_path=config_path,
        payload=payload,
        source_report=source_report,
        phase_state={
            "control_plane": {
                "hops": {
                    "1.32": {
                        "status": "updating",
                        "from_version": "1.31",
                        "target_version": "1.32",
                        "provider_update_attempted": True,
                    }
                }
            }
        },
    )
    _attach_pending_control_plane_operation(checkpoint_path, target_version="1.32")
    checkpoint = json.loads(checkpoint_path.read_text(encoding="utf-8"))
    checkpoint["operation_intent"]["provider_operations"][0]["provider_operation_id"] = (
        "operation-control-plane-different"
    )
    migration._write_checkpoint(checkpoint_path, checkpoint)  # noqa: SLF001
    runner = _FakeCommandRunner(
        cluster={
            "metadata": {
                "id": "cluster-123",
                "name": "external-cluster",
                "resource_version": 17,
            },
            "spec": {"control_plane": {"version": "1.32"}},
            "status": {
                "state": "RUNNING",
                "control_plane": {"version": "1.32"},
            },
        }
    )
    checkpoint = json.loads(checkpoint_path.read_text(encoding="utf-8"))
    monkeypatch.setattr(
        migration,
        "_revalidate_protected_login_sessions",
        lambda **_kwargs: [],
    )

    with pytest.raises(RuntimeError, match="one exact accepted provider operation journal"):
        migration._execute_external_node_template_upgrade_phase(  # noqa: SLF001
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            target_ref="external-cluster",
            kube_context="external-context",
            nebius_api=runner.nebius_api,
            command_runner=runner,
            checkpoint_writer=lambda: None,
        )

    assert not any(
        call[0][:4]
        in {
            ("nebius", "mk8s", "cluster", "update"),
            ("nebius", "mk8s", "node-group", "update"),
        }
        for call in runner.calls
    )


def test_worker_preflight_prefers_specific_group_identity_over_generic_nodeset() -> None:
    worker_groups = [
        (
            "nodegroup-gpu",
            {
                "node_group_id": "nodegroup-gpu",
                "node_group_name": "worker-gpu-0",
                "labels": {
                    "nebius.com/node-group-id": "nodegroup-gpu",
                    "nebius.com/node-group": "worker-gpu-0",
                    "slurm.nebius.ai/nodeset": "worker",
                    "slurm.nebius.ai/nodeset-name": "worker-gpu",
                },
            },
        ),
        (
            "nodegroup-cpu",
            {
                "node_group_id": "nodegroup-cpu",
                "node_group_name": "worker-cpu-0",
                "labels": {
                    "nebius.com/node-group-id": "nodegroup-cpu",
                    "nebius.com/node-group": "worker-cpu-0",
                    "slurm.nebius.ai/nodeset": "worker",
                    "slurm.nebius.ai/nodeset-name": "worker-cpu",
                },
            },
        ),
    ]
    nodes = [
        {
            "metadata": {
                "name": "computeinstance-cpu",
                "labels": {
                    "nebius.com/node-group-id": "nodegroup-cpu",
                    "slurm.nebius.ai/nodeset": "worker",
                    "slurm.nebius.ai/nodeset-name": "worker-cpu",
                },
            }
        },
        {
            "metadata": {
                "name": "computeinstance-gpu",
                "labels": {
                    "nebius.com/node-group-id": "nodegroup-gpu",
                    "slurm.nebius.ai/nodeset": "worker",
                    "slurm.nebius.ai/nodeset-name": "worker-gpu",
                },
            }
        },
    ]

    grouped = migration._worker_nodes_by_source_group(  # noqa: SLF001
        nodes=nodes,
        worker_groups=worker_groups,
    )

    assert [item["metadata"]["name"] for item in grouped["nodegroup-gpu"]] == [
        "computeinstance-gpu"
    ]
    assert [item["metadata"]["name"] for item in grouped["nodegroup-cpu"]] == [
        "computeinstance-cpu"
    ]


def _external_upgrade_slurm_runner(
    *,
    queue_outputs: list[str],
    calls: list[tuple[str, ...]],
    pending_queue_outputs: list[str] | None = None,
) -> Callable[..., SoperatorMigrationCommandResult]:
    pending_outputs = pending_queue_outputs if pending_queue_outputs is not None else []
    partition_state = "UP"
    held_job_ids: set[str] = set()
    requeued_job_ids: set[str] = set()

    def _job_record(job_id: str) -> str:
        user = "bob" if job_id == "43" else "alice"
        name = "restartable-eval" if job_id == "43" else "restartable-train"
        if job_id in held_job_ids:
            state, reason, priority, restarts, node_list = (
                "PENDING",
                "JobHeldUser",
                "0",
                "1",
                "(null)",
            )
        elif job_id in requeued_job_ids:
            state, reason, priority, restarts, node_list = (
                "PENDING",
                "Resources",
                "100",
                "1",
                "(null)",
            )
        else:
            state, reason, priority, restarts, node_list = (
                "RUNNING",
                "None",
                "100",
                "0",
                "worker-gpu-0-0",
            )
        return (
            f"JobId={job_id} JobName={name} UserId={user}(1000) JobState={state} "
            f"Reason={reason} Priority={priority} Requeue=1 Restarts={restarts} "
            "BatchFlag=1 RunTime=00:05:00 TimeLimit=01:00:00 "
            f"SubmitTime={'2026-07-11T10:05:00' if job_id in requeued_job_ids else '2026-07-11T10:00:00'} "
            "EligibleTime=2026-07-11T10:00:00 "
            "AccrueTime=2026-07-11T10:00:00 StartTime=2026-07-11T10:01:00 "
            "EndTime=2026-07-11T11:01:00 LastSchedEval=2026-07-11T10:00:59 "
            f"Partition=gpu AllocNode:Sid=login-0:1234 NodeList={node_list}"
        )

    def runner(
        args: Sequence[str],
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorMigrationCommandResult:
        nonlocal partition_state
        del input_text, timeout_seconds, check
        command = tuple(str(item) for item in args)
        calls.append(command)
        if command == (
            "kubectl",
            "--context",
            "external-context",
            "-n",
            "soperator",
            "get",
            "pods",
            "-o",
            "json",
            "--request-timeout=20s",
        ):
            return SoperatorMigrationCommandResult(
                command,
                0,
                json.dumps(
                    {
                        "items": [
                            {
                                "metadata": {"name": "login-0"},
                                "status": {"phase": "Running"},
                            }
                        ]
                    }
                ),
                "",
            )
        if command[:8] == (
            "kubectl",
            "--context",
            "external-context",
            "-n",
            "soperator",
            "exec",
            "login-0",
            "--",
        ):
            if command[8:] == ("scontrol", "show", "nodes"):
                return SoperatorMigrationCommandResult(
                    command,
                    0,
                    "NodeName=worker-gpu-0-0 NodeHostName=worker-gpu-0-0 Partitions=gpu",
                    "",
                )
            if command[8:11] == ("scontrol", "show", "node") and command[-1] == "-o":
                return SoperatorMigrationCommandResult(
                    command,
                    0,
                    f"NodeName={command[11]} Partitions=gpu State=IDLE",
                    "",
                )
            if command[8:11] == ("scontrol", "show", "job") and command[-1] == "-o":
                return SoperatorMigrationCommandResult(
                    command,
                    0,
                    _job_record(command[11]),
                    "",
                )
            if command[8:10] == ("scontrol", "requeuehold"):
                held_job_ids.update(command[10:])
                requeued_job_ids.update(command[10:])
                return SoperatorMigrationCommandResult(command, 0, "", "")
            if command[8:10] == ("scontrol", "release"):
                held_job_ids.difference_update(command[10:])
                return SoperatorMigrationCommandResult(command, 0, "", "")
            if command[8:] == ("scontrol", "show", "partition", "-o"):
                return SoperatorMigrationCommandResult(
                    command,
                    0,
                    f"PartitionName=gpu State={partition_state} Nodes=worker-gpu-0-0\n",
                    "",
                )
            if command[8:10] == ("scontrol", "update"):
                state_arg = next(
                    (item for item in command[10:] if item.startswith("State=")),
                    "",
                )
                if state_arg:
                    partition_state = state_arg.split("=", 1)[1]
                return SoperatorMigrationCommandResult(command, 0, "", "")
            if command[8:10] == ("squeue", "-h"):
                if "PENDING" in command:
                    return SoperatorMigrationCommandResult(
                        command,
                        0,
                        pending_outputs.pop(0) if pending_outputs else "",
                        "",
                    )
                return SoperatorMigrationCommandResult(command, 0, queue_outputs.pop(0), "")
        return SoperatorMigrationCommandResult(command, 0, "ok\n", "")

    return runner


