def test_active_login_ssh_session_probe_rejects_failing_ss(tmp_path: Path) -> None:
    fake_ss = tmp_path / "ss"
    fake_ss.write_text("#!/bin/sh\nexit 1\n", encoding="utf-8")
    fake_ss.chmod(0o755)

    def runner(
        args: Sequence[str],
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorMigrationCommandResult:
        del input_text, timeout_seconds, check
        command = tuple(str(item) for item in args)
        completed = subprocess.run(
            ("/bin/sh", "-ceu", command[-1]),
            check=False,
            capture_output=True,
            text=True,
            env={"PATH": f"{tmp_path}:/usr/bin:/bin"},
        )
        return SoperatorMigrationCommandResult(
            command,
            completed.returncode,
            completed.stdout,
            completed.stderr,
        )

    probe = migration._active_login_ssh_session_probe(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        pod_names=("source-login-0",),
    )

    assert probe["status"] == "unknown"
    assert probe["pods"][0]["status"] == "unknown"
    assert probe["pods"][0]["detail"] == "ss session probe failed"


def test_active_login_ssh_session_probe_excludes_preauth_connections(tmp_path: Path) -> None:
    fake_ss = tmp_path / "ss"
    fake_ss.write_text(
        "#!/bin/sh\nprintf '%s\\n' 'ESTABLISHED one' 'ESTABLISHED two'\n",
        encoding="utf-8",
    )
    fake_ss.chmod(0o755)
    fake_ps = tmp_path / "ps"
    fake_ps.write_text(
        "#!/bin/sh\nprintf '%s\\n' "
        "'sshd: /usr/sbin/sshd -D [listener]' "
        "'sshd: [accepted]' 'sshd: root@pts/0'\n",
        encoding="utf-8",
    )
    fake_ps.chmod(0o755)
    awk = shutil.which("awk")
    sleep = shutil.which("sleep")
    assert awk is not None
    assert sleep is not None
    (tmp_path / "awk").symlink_to(awk)
    (tmp_path / "sleep").symlink_to(sleep)

    def runner(
        args: Sequence[str],
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorMigrationCommandResult:
        del input_text, timeout_seconds, check
        command = tuple(str(item) for item in args)
        completed = subprocess.run(
            ("/bin/sh", "-ceu", command[-1]),
            check=False,
            capture_output=True,
            text=True,
            env={"PATH": str(tmp_path)},
        )
        return SoperatorMigrationCommandResult(
            command,
            completed.returncode,
            completed.stdout,
            completed.stderr,
        )

    probe = migration._active_login_ssh_session_probe(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        pod_names=("source-login-0",),
    )

    assert probe["status"] == "checked"
    assert probe["active_sessions"] == 1


def test_active_login_ssh_session_probe_counts_only_established_procfs_ssh(
    tmp_path: Path,
) -> None:
    tcp4 = tmp_path / "tcp"
    tcp6 = tmp_path / "tcp6"
    header = "sl local_address rem_address st tx_queue rx_queue tr tm->when retrnsmt uid timeout"
    tcp4.write_text(
        "\n".join(
            (
                header,
                "0: 00000000:0016 00000000:0000 0A 0:0 0:0 00 0 0 0 0",
                "1: 0100007F:0016 0100007F:C001 01 0:0 0:0 00 0 0 0 0",
                "2: 0100007F:1234 0100007F:C002 01 0:0 0:0 00 0 0 0 0",
            )
        )
        + "\n",
        encoding="utf-8",
    )
    tcp6.write_text(
        "\n".join(
            (
                header,
                "0: 00000000000000000000000000000000:0016 "
                "00000000000000000000000000000000:0000 01 0:0 0:0 00 0 0 0 0",
            )
        )
        + "\n",
        encoding="utf-8",
    )
    awk = shutil.which("awk")
    ps = shutil.which("ps")
    sleep = shutil.which("sleep")
    assert awk is not None
    assert ps is not None
    assert sleep is not None
    (tmp_path / "awk").symlink_to(awk)
    (tmp_path / "ps").symlink_to(ps)
    (tmp_path / "sleep").symlink_to(sleep)

    def runner(
        args: Sequence[str],
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorMigrationCommandResult:
        del input_text, timeout_seconds, check
        command = tuple(str(item) for item in args)
        script = (
            command[-1]
            .replace("/proc/net/tcp6", str(tcp6))
            .replace(
                "/proc/net/tcp",
                str(tcp4),
            )
        )
        completed = subprocess.run(
            ("/bin/sh", "-ceu", script),
            check=False,
            capture_output=True,
            text=True,
            env={"PATH": str(tmp_path)},
        )
        return SoperatorMigrationCommandResult(
            command,
            completed.returncode,
            completed.stdout,
            completed.stderr,
        )

    probe = migration._active_login_ssh_session_probe(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        pod_names=("source-login-0",),
    )

    assert probe["status"] == "checked"
    assert probe["active_sessions"] == 2


def test_active_login_ssh_session_probe_ignores_transient_readiness_connection(
    tmp_path: Path,
) -> None:
    fake_ss = tmp_path / "ss"
    sample_count = tmp_path / "sample-count"
    fake_ss.write_text(
        "#!/bin/sh\n"
        f"count_file={json.dumps(str(sample_count))}\n"
        "count=0\n"
        'if [ -f "$count_file" ]; then count=$(cat "$count_file"); fi\n'
        "count=$((count + 1))\n"
        'printf \'%s\\n\' "$count" > "$count_file"\n'
        "if [ \"$count\" -eq 1 ]; then printf '%s\\n' 'ESTABLISHED readiness'; fi\n",
        encoding="utf-8",
    )
    fake_ss.chmod(0o755)
    fake_ps = tmp_path / "ps"
    fake_ps.write_text(
        "#!/bin/sh\nprintf '%s\\n' 'sshd: /usr/sbin/sshd -D [listener]'\n",
        encoding="utf-8",
    )
    fake_ps.chmod(0o755)
    for command_name in ("awk", "cat", "sleep"):
        command = shutil.which(command_name)
        assert command is not None
        (tmp_path / command_name).symlink_to(command)

    def runner(
        args: Sequence[str],
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorMigrationCommandResult:
        del input_text, timeout_seconds, check
        command = tuple(str(item) for item in args)
        completed = subprocess.run(
            ("/bin/sh", "-ceu", command[-1]),
            check=False,
            capture_output=True,
            text=True,
            env={"PATH": str(tmp_path)},
        )
        return SoperatorMigrationCommandResult(
            command,
            completed.returncode,
            completed.stdout,
            completed.stderr,
        )

    probe = migration._active_login_ssh_session_probe(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        pod_names=("source-login-0",),
    )

    assert probe["status"] == "checked"
    assert probe["active_sessions"] == 0


