def test_in_place_login_handoff_binding_uses_locked_source_provider_version() -> None:
    checkpoint = {
        "phase_state": {},
        "operation_intent": {
            "intended_postcondition": {
                "mk8s": {
                    "node_groups": [
                        {
                            "id": "login-group-id",
                            "name": "login",
                            "role": "login",
                            "source": {"kubernetes_version": "1.31"},
                            "target": {"kubernetes_version": "1.32"},
                        }
                    ]
                }
            }
        },
    }

    binding = migration._checkpoint_in_place_login_handoff_binding(  # noqa: SLF001
        checkpoint=checkpoint,
        checkpoint_writer=None,
    )

    assert binding["mode"] == migration.COMPUTE_MIGRATION_MODE_IN_PLACE
    assert binding["node_group_id"] == "login-group-id"
    assert binding["workload_kubernetes_version"] == "1.31"
    assert binding["provider_target_kubernetes_version"] == "1.32"


def test_rootfs_handoff_uses_one_snapshot_for_login_and_worker_contracts() -> None:
    calls: list[tuple[str, ...]] = []

    def runner(
        args: Sequence[str],
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorMigrationCommandResult:
        del input_text, timeout_seconds, check
        command = tuple(str(item) for item in args)
        calls.append(command)
        return SoperatorMigrationCommandResult(
            command,
            0,
            json.dumps(
                {
                    "apiVersion": "v1",
                    "kind": "List",
                    "items": [
                        {
                            "apiVersion": "apps.kruise.io/v1beta1",
                            "kind": "StatefulSet",
                            "metadata": {"name": "login"},
                        },
                        {
                            "apiVersion": "slurm.nebius.ai/v1alpha1",
                            "kind": "NodeSet",
                            "metadata": {"name": "worker"},
                        },
                    ],
                }
            ),
            "",
        )

    snapshot = migration._target_rootfs_handoff_consumer_snapshot(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        values={"nodesets": [{"name": "worker"}]},
    )

    assert set(snapshot) == {
        ("login-statefulset", "login"),
        ("worker-nodeset", "worker"),
    }
    assert len(calls) == 1
    assert "statefulsets.apps.kruise.io/login" in calls[0]
    assert "nodeset/worker" in calls[0]
    assert "--ignore-not-found" in calls[0]


