def test_final_partition_restore_precedes_destructive_cleanup_and_records_exact_intent(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(migration, "validate_bridge_journal", lambda _journal: None)
    monkeypatch.setattr(
        migration,
        "advance_bridge_stage",
        lambda journal, stage: journal.update({"stage": stage.value}),
    )
    record = _slurm_partition_pause_record_fixture("main")
    checkpoint: dict[str, Any] = {
        **_journal_contract_fields(),
        "phase_state": {},
        "slurm": {"paused_partitions": [record.as_payload()]},
    }
    bridge = _new_controller_bridge_lifecycle_journal(checkpoint)
    _advance_controller_bridge_fixture_to_source_ha(bridge)
    _advance_controller_bridge_fixture_to_target_ha(bridge)
    _advance_controller_bridge_fixture_to_target_singleton(bridge)
    checkpoint["controller_bridge"] = bridge
    action_journal = migration.ensure_slurm_action_journal(checkpoint)
    checkpoint["final_health"] = {
        "status": "passed",
        "action_journal_generation": slurm_action_journal_generation(action_journal),
        "authority_epoch": "target-singleton-epoch",
    }
    restored: list[tuple[str, ...]] = []
    decisions: list[Mapping[str, Any]] = []
    retained_substrate_checks: list[str] = []
    final_health_revalidations: list[dict[str, Any]] = []
    cleanup_proof_order: list[str] = []

    def _preservation_proof(**kwargs: Any) -> list[str]:
        journal = kwargs["journal"]
        binding = migration._controller_bridge_cleanup_action_binding(  # noqa: SLF001
            kwargs["checkpoint"]
        )
        journal["preservation_jobs"]["verifications"] = [
            item
            for item in journal["preservation_jobs"]["verifications"]
            if item.get("stage") != "pre-cleanup"
        ]
        journal["preservation_jobs"]["verifications"].append(
            {
                "stage": "pre-cleanup",
                "status": "verified",
                "jobs": {},
                "verified_at": "2026-07-12T10:20:30Z",
                **binding,
            }
        )
        return ["Fresh preservation proof recorded while bridge resources remained."]

    monkeypatch.setattr(
        migration,
        "_controller_bridge_cleanup_required_gates",
        lambda _checkpoint: None,
    )
    monkeypatch.setattr(
        migration,
        "_verify_controller_bridge_preservation_jobs",
        _preservation_proof,
    )
    monkeypatch.setattr(
        migration,
        "_prove_controller_bridge_cleanup_target_singleton",
        lambda **_kwargs: (
            cleanup_proof_order.append("prove")
            or {
                "pvc_name": "target-state",
                "pvc_uid": "target-state-pvc-uid",
                "pv_name": "target-state-pv",
                "pv_uid": "target-state-pv-uid",
                "state_path": "/mnt/controller-spool/current",
            }
        ),
    )
    monkeypatch.setattr(
        migration,
        "_revalidate_target_singleton_before_controller_bridge_cleanup",
        lambda **_kwargs: cleanup_proof_order.append("revalidate"),
    )
    monkeypatch.setattr(
        migration,
        "_controller_bridge_require_stopped_retained_substrate",
        lambda **_kwargs: retained_substrate_checks.append("verified"),
    )
    monkeypatch.setattr(
        migration,
        "_restore_external_upgrade_slurm_partitions",
        lambda **kwargs: restored.append(tuple(item.partition for item in kwargs["records"])),
    )

    def _revalidate_final_health(binding: Mapping[str, Any]) -> None:
        assert action_journal["broker_mode"] == migration.SLURM_ACTION_ADMISSION_CLOSED
        assert action_journal["target_finalization_boundary"]
        final_health_revalidations.append(dict(binding))
        checkpoint["final_health"] = {"status": "passed", **binding}

    restore_kwargs = {
        "checkpoint": checkpoint,
        "nebius_api": object(),
        "command_runner": lambda args, **_kwargs: SoperatorMigrationCommandResult(
            tuple(args), 0, "", ""
        ),
        "kube_context": "external-context",
        "checkpoint_writer": None,
        "slurm_decision_recorder": decisions.append,
        "final_health_revalidator": _revalidate_final_health,
    }

    mutation, lines = migration._restore_slurm_partitions_before_controller_bridge_cleanup(  # noqa: SLF001
        **restore_kwargs
    )

    assert mutation is True
    assert len(final_health_revalidations) == 1
    assert final_health_revalidations[0]["target_action_journal_generation"] == 0
    assert restored == [("main",)]
    assert retained_substrate_checks == ["verified"]
    assert cleanup_proof_order == ["revalidate", "prove"]
    assert decisions[0]["action"] == "scheduling-pause-restored"
    assert checkpoint["slurm"]["final_partition_restore"]["status"] == "restored"
    assert bridge["stage"] == migration.BridgeStage.PARTITIONS_RESTORED.value
    assert bridge["cleanup"]["intent_at"] == ""
    assert bridge["cleanup"]["kubernetes_operations"] == {}
    assert bridge["cleanup"]["node_group_operations"] == {}
    assert "before destructive bridge cleanup" in lines[-1]


def test_in_progress_partition_restore_reconciles_late_target_retirement(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    gpu = _slurm_partition_pause_record_fixture("gpu")
    background = _slurm_partition_pause_record_fixture("background")
    old_hash = migration._fingerprint(  # noqa: SLF001
        {"restored": [gpu.as_payload(), background.as_payload()], "target_retired": []}
    )
    restore: dict[str, Any] = {
        "status": "restoring",
        "records_sha256": old_hash,
        "partitions": [gpu.as_payload(), background.as_payload()],
    }
    bridge_restore: dict[str, Any] = {
        "status": "restoring",
        "records_sha256": old_hash,
    }
    live_gpu = _slurm_partition_state_fixture("gpu", "UP")
    monkeypatch.setattr(
        migration,
        "_external_upgrade_partition_state_snapshot",
        lambda **_kwargs: (live_gpu,),
    )
    records_payload = [gpu.as_payload()]
    retired_payload = [background.as_payload()]
    new_hash = migration._fingerprint(  # noqa: SLF001
        {"restored": records_payload, "target_retired": retired_payload}
    )
    checkpoints: list[dict[str, Any]] = []

    repaired = migration._reconcile_in_progress_partition_restore_target_retirement(  # noqa: SLF001
        checkpoint={
            "controller_bridge": {
                "stage": migration.BridgeStage.HANDOFF_VALIDATED.value,
            }
        },
        restore=restore,
        bridge_restore=bridge_restore,
        all_records=(gpu, background),
        records=(gpu,),
        records_payload=records_payload,
        retired_records_payload=retired_payload,
        records_sha256=new_hash,
        command_runner=lambda *_args, **_kwargs: None,  # type: ignore[arg-type]
        kube_context="external-context",
        checkpoint_writer=lambda: checkpoints.append(copy.deepcopy(restore)),
    )

    assert repaired is True
    assert restore["records_sha256"] == new_hash
    assert restore["partitions"] == records_payload
    assert restore["target_retired_partitions"] == ["background"]
    assert restore["superseded_restore_plan_sha256"] == old_hash
    assert bridge_restore["records_sha256"] == new_hash
    assert checkpoints


def test_prepare_jail_persistent_mount_payload_patches_target_values() -> None:
    payload = _payload()
    payload["apps"]["charts"][0]["values"] = {"nodesets": [{"name": "worker"}]}

    patched, state = migration._prepare_jail_persistent_mount_payload(  # noqa: SLF001
        payload=payload,
        target_ref="external-cluster",
        jail_persistent_mounts=("/data=/mnt/jail/shared/data",),
        populate_jail_refresh="auto",
    )

    values = patched["apps"]["charts"][0]["values"]
    assert state["status"] == "planned"
    assert state["copy_required"] is True
    assert state["auto_preserve_paths"] == ["/home", "/data", "/scripts", "/models"]
    decision_status = {item["mount_path"]: item["status"] for item in state["decisions"]}
    assert decision_status == {
        "/home": "adopted-in-place",
        "/data": "explicit",
        "/scripts": "adopted-in-place",
        "/models": "adopted-in-place",
    }
    assert values["jailPersistentMounts"] == [
        {"mountPath": "/home", "localPath": "/mnt/jail/home"},
        {"mountPath": "/data", "localPath": "/mnt/jail/shared/data"},
        {"mountPath": "/scripts", "localPath": "/mnt/jail/scripts"},
        {"mountPath": "/models", "localPath": "/mnt/jail/models"},
    ]
    assert state["migration"]["status"] == "planned"
    assert state["migration"]["entries"] == [
        {
            "name": "jail-persistent-migration-data",
            "mount_path": "/data",
            "source_path": "/mnt/jail/data",
            "source_store_path": "/data",
            "target_local_path": "/mnt/jail/shared/data",
            "target_store_path": "/shared/data",
            "marker_path": "/mnt/jail/.cxcli/persistent-migrations/data.json",
            "marker_store_path": "/.cxcli/persistent-migrations/data.json",
            "bytes_planned": None,
            "pvc_name": "",
            "status": "planned",
        },
    ]
    assert values["jailRootfs"]["store"]["rootfsPath"] == "/mnt/jail/.cxcli/rootfs"
    assert values["jailRootfs"]["adoption"]["activeSource"] == "legacy-rootfs"
    assert "sfs" not in values
    phase_ids = migration._phase_ids_with_jail_persistent_mount_prerequisites(  # noqa: SLF001
        phase_ids=("customer-approval",),
        payload=patched,
        target_ref="external-cluster",
    )
    assert phase_ids == ("customer-approval", "populate-jail-refresh")


