def test_suspend_legacy_flux_fences_parent_kustomization_before_helmrelease() -> None:
    class _FluxParentRunner:
        def __init__(self) -> None:
            self.calls: list[tuple[str, ...]] = []
            self.kustomization_suspended = False
            self.helmrelease_suspended = False

        def __call__(
            self,
            args,
            *,
            input_text: str | None = None,
            timeout_seconds: int = 300,
            check: bool = True,
        ) -> SoperatorMigrationCommandResult:
            del input_text, timeout_seconds, check
            command = tuple(str(item) for item in args)
            self.calls.append(command)
            if "kustomization/flux-system" in command and "get" in command:
                payload = {
                    "metadata": {
                        "uid": "kustomization-uid",
                        "resourceVersion": "42",
                    },
                    "spec": {"suspend": self.kustomization_suspended},
                }
                return SoperatorMigrationCommandResult(command, 0, json.dumps(payload), "")
            if "kustomization/flux-system" in command and "patch" in command:
                self.kustomization_suspended = True
                return SoperatorMigrationCommandResult(command, 0, "patched", "")
            if "helmrelease" in command and "patch" in command:
                assert self.kustomization_suspended
                self.helmrelease_suspended = True
                return SoperatorMigrationCommandResult(command, 0, "patched", "")
            if "helmreleases" in command and "get" in command:
                payload = {
                    "items": [
                        {
                            "metadata": {
                                "name": "soperator-fluxcd",
                                "labels": {
                                    "kustomize.toolkit.fluxcd.io/name": "flux-system",
                                    "kustomize.toolkit.fluxcd.io/namespace": "flux-system",
                                },
                            },
                            "spec": {"suspend": self.helmrelease_suspended},
                        }
                    ]
                }
                return SoperatorMigrationCommandResult(command, 0, json.dumps(payload), "")
            raise AssertionError(command)

    runner = _FluxParentRunner()
    phase: dict[str, Any] = {}

    changed = migration._suspend_legacy_flux_helmreleases(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        phase=phase,
    )

    assert runner.kustomization_suspended
    assert runner.helmrelease_suspended
    assert changed
    assert phase["suspended_flux_kustomizations"] == ["flux-system/flux-system"]
    assert phase["source_flux_reconciliation_fence"]["kustomizations"] == [
        "flux-system/flux-system"
    ]
    kustomization_patch = next(
        index
        for index, command in enumerate(runner.calls)
        if "patch" in command and "kustomization/flux-system" in command
    )
    helmrelease_patch = next(
        index
        for index, command in enumerate(runner.calls)
        if "patch" in command and "helmrelease" in command
    )
    assert kustomization_patch < helmrelease_patch


def test_suspend_legacy_flux_tolerates_parent_status_resource_version_churn() -> None:
    class _FluxParentStatusChurnRunner:
        def __init__(self) -> None:
            self.kustomization_suspended = False
            self.helmrelease_suspended = False

        def __call__(
            self,
            args,
            *,
            input_text: str | None = None,
            timeout_seconds: int = 300,
            check: bool = True,
        ) -> SoperatorMigrationCommandResult:
            del input_text, timeout_seconds, check
            command = tuple(str(item) for item in args)
            if "kustomization/flux-system" in command and "get" in command:
                payload = {
                    "metadata": {
                        "uid": "kustomization-uid",
                        # Flux status reconciliation can advance this between the
                        # read and the spec-only suspend patch.
                        "resourceVersion": "43",
                    },
                    "spec": {"suspend": self.kustomization_suspended},
                }
                return SoperatorMigrationCommandResult(command, 0, json.dumps(payload), "")
            if "kustomization/flux-system" in command and "patch" in command:
                patch = json.loads(command[command.index("-p") + 1])
                assert {
                    "op": "test",
                    "path": "/metadata/uid",
                    "value": "kustomization-uid",
                } in patch
                assert not any(
                    operation.get("path") == "/metadata/resourceVersion" for operation in patch
                )
                self.kustomization_suspended = True
                return SoperatorMigrationCommandResult(command, 0, "patched", "")
            if "helmrelease" in command and "patch" in command:
                assert self.kustomization_suspended
                self.helmrelease_suspended = True
                return SoperatorMigrationCommandResult(command, 0, "patched", "")
            if "helmreleases" in command and "get" in command:
                payload = {
                    "items": [
                        {
                            "metadata": {
                                "name": "soperator-fluxcd",
                                "labels": {
                                    "kustomize.toolkit.fluxcd.io/name": "flux-system",
                                    "kustomize.toolkit.fluxcd.io/namespace": "flux-system",
                                },
                            },
                            "spec": {"suspend": self.helmrelease_suspended},
                        }
                    ]
                }
                return SoperatorMigrationCommandResult(command, 0, json.dumps(payload), "")
            raise AssertionError(command)

    runner = _FluxParentStatusChurnRunner()

    migration._suspend_legacy_flux_helmreleases(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        phase={},
    )

    assert runner.kustomization_suspended
    assert runner.helmrelease_suspended


@pytest.mark.parametrize("profile_id", ["v2-to-target", "v3-to-target"])
def test_scale_down_legacy_soperator_controller_deployments(profile_id: str) -> None:
    runner = _FakeCommandRunner(
        live_kubernetes_resources={
            "deployment": [
                {
                    "metadata": {
                        "name": "soperator-controller-manager",
                        "namespace": "soperator-system",
                        "labels": {
                            "helm.sh/chart": "helm-soperator-2.0.5",
                            "app.kubernetes.io/version": "2.0.5",
                        },
                        "annotations": {
                            "meta.helm.sh/release-name": "soperator-controller",
                        },
                    },
                    "spec": {"replicas": 1},
                    "status": {"availableReplicas": 1, "readyReplicas": 1},
                },
                {
                    "metadata": {
                        "name": "soperator-manager",
                        "namespace": "soperator",
                        "labels": {
                            "helm.sh/chart": "soperator-4.0.1-ps.1",
                            "app.kubernetes.io/version": "4.0.1",
                        },
                        "annotations": {"meta.helm.sh/release-name": "soperator"},
                    },
                    "spec": {"replicas": 1},
                    "status": {"availableReplicas": 1, "readyReplicas": 1},
                },
            ],
            "mutatingwebhookconfiguration": [
                {"metadata": {"name": "soperator-controller-mutating-webhook-configuration"}},
                {"metadata": {"name": "soperator-mutating-webhook-configuration"}},
            ],
            "validatingwebhookconfiguration": [
                {"metadata": {"name": "soperator-controller-validating-webhook-configuration"}},
                {"metadata": {"name": "soperator-validating-webhook-configuration"}},
            ],
        }
    )
    phase: dict[str, Any] = {}

    changed, lines = migration._scale_down_legacy_soperator_controllers(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        phase=phase,
        target_version="4.0.1-ps.1",
        profile_group=soperator_migration_profile_group(profile_id),
    )

    assert changed is True
    assert lines == [
        "Disabled exact source Soperator admission webhook UIDs before target takeover: "
        "MutatingWebhookConfiguration/soperator-controller-mutating-webhook-configuration, "
        "ValidatingWebhookConfiguration/soperator-controller-validating-webhook-configuration.",
        "Scaled down old source Soperator controller deployments before target "
        "takeover: soperator-system/soperator-controller-manager.",
    ]
    assert [item["ref"] for item in phase["deleted_source_controller_admission_webhooks"]] == [
        "MutatingWebhookConfiguration/soperator-controller-mutating-webhook-configuration",
        "ValidatingWebhookConfiguration/soperator-controller-validating-webhook-configuration",
    ]
    assert phase["scaled_source_controller_deployments"] == [
        "soperator-system/soperator-controller-manager"
    ]
    deployments = runner.live_kubernetes_resources["deployment"]
    source = deployments[0]
    target = deployments[1]
    assert source["spec"]["replicas"] == 0
    assert source["status"]["availableReplicas"] == 0
    assert target["spec"]["replicas"] == 1
    for resource_type in (
        "mutatingwebhookconfiguration",
        "validatingwebhookconfiguration",
    ):
        resources = runner.live_kubernetes_resources[resource_type]
        source_webhook, target_webhook = resources
        assert source_webhook["webhooks"] == []
        assert target_webhook["webhooks"]
    fence = phase["source_controller_reconciliation_fence"]
    assert fence["status"] == "verified"
    assert fence["deployments"][0]["pods_absent"] is True


