def _collect_provider_mk8s_status(
    runner: _FakeCommandRunner,
    checkpoint: Mapping[str, Any],
    *,
    phase_id: str = "external-node-template-upgrade",
    source_report: Mapping[str, Any] | None = None,
) -> migration.SoperatorMigrationStatusSignal:
    if source_report is None:
        source_node_groups: dict[str, Any] = {}
        for node_group in runner.existing_node_groups:
            metadata = node_group.get("metadata")
            metadata_map = metadata if isinstance(metadata, Mapping) else {}
            node_group_id = str(metadata_map.get("id", "") or "").strip()
            node_group_name = str(metadata_map.get("name", "") or node_group_id).strip()
            if not node_group_name:
                continue
            source_node_groups[node_group_name] = {
                "node_group_id": node_group_id,
                "node_group_name": node_group_name,
            }
        source_report = {"snapshot": {"node_groups": source_node_groups}}
    return migration._collect_mk8s_status(
        nebius_api=runner.nebius_api,
        checkpoint=checkpoint,
        phase_id=phase_id,
        payload=_payload(),
        source_report=source_report,
        target_ref="external-cluster",
    )


def _provider_checkpoint() -> dict[str, Any]:
    return {
        "phase_state": {
            "external-node-template-upgrade": {"cluster_id": "cluster-123"},
            "rolling-compute-migration": {
                "cluster_id": "cluster-123",
                "target_node_groups": {},
            },
        }
    }


def _rolling_target_state(
    *,
    role: str,
    name: str,
    node_group_id: str,
) -> dict[str, Any]:
    return {
        "id": node_group_id,
        "name": name,
        "role": role,
        "compute_role": "worker" if role.startswith("worker:") else role,
        "replacement_binding": {
            "original_node_group_id": "source-" + node_group_id,
            "original_node_group_name": "source-" + name,
            "replacement_node_group_id": node_group_id,
            "replacement_node_group_name": name,
            "replacement_role": role,
        },
        "operation": {
            "operation_kind": "mk8s-node-group-create",
            "resource_id": node_group_id,
            "attempt_state": "provider-terminal",
            "verified_postcondition": {
                "name": name,
                "node_group_id": node_group_id,
            },
        },
    }


def _mk8s_status_row_cells(summary: str, group: str) -> list[str]:
    for line in summary.splitlines():
        cells = line.split()
        if cells and cells[0] == group:
            return cells
    raise AssertionError(f"MK8s status row not found for {group!r}:\n{summary}")


def test_mk8s_status_external_control_plane_keeps_source_groups_serving() -> None:
    runner = _FakeCommandRunner(
        existing_node_groups=[
            {
                "metadata": {"id": "nodegroup-system", "name": "system"},
                "spec": {"version": "1.31"},
                "status": {
                    "ready_node_count": 1,
                    "target_node_count": 1,
                    "node_count": 1,
                    "state": "RUNNING",
                },
            }
        ]
    )
    checkpoint = _provider_checkpoint()
    checkpoint["phase_state"]["external-node-template-upgrade"]["control_plane"] = {
        "hops": {
            "1.32": {
                "status": "updating",
                "from_version": "1.31",
                "target_version": "1.32",
            }
        }
    }
    messages: list[str] = []
    reporter = migration.SoperatorMigrationStatusReporter(
        emit=messages.append,
        nebius_api=runner.nebius_api,
        command_runner=runner,
        kube_context="external-context",
        checkpoint=checkpoint,
        payload=_payload(),
        source_report={
            "snapshot": {
                "node_groups": {
                    "system": {
                        "node_group_id": "nodegroup-system",
                        "node_group_name": "system",
                    }
                }
            }
        },
        target_ref="external-cluster",
        phase_ids=("external-node-template-upgrade",),
        poll_interval_seconds=0,
    )

    snapshot = reporter.set_phase("external-node-template-upgrade")

    assert snapshot is not None
    assert snapshot.state == "upgrading"
    assert (
        "phase external-node-template-upgrade [MK8s control-plane-only upgrade] (upgrading)"
    ) in snapshot.summary
    assert "MK8s Control Plane upgrading: control-plane hop 1.31 -> 1.32 in progress" in (
        snapshot.summary
    )
    assert "MK8s Node Groups serving:" in snapshot.summary
    assert (
        "total=1 provider-current=1 provider-updating=0 provider-outdated=0 ready/current=1/1"
    ) in snapshot.summary
    assert _mk8s_status_row_cells(snapshot.summary, "system")[:8] == [
        "system",
        "RUNNING",
        "1.31",
        "1",
        "1",
        "0",
        "0",
        "1/1",
    ]
    assert runner.nebius_api.calls == [("node_group.list", "cluster-123")]
    assert messages == [snapshot.summary]


def test_populate_jail_reporter_puts_phase_substage_before_cluster_table(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(
        migration,
        "_collect_populate_jail_status",
        lambda **_kwargs: migration.SoperatorMigrationStatusSignal(
            "Jail Upgrade", "upgrading", "immutable child inventory captured"
        ),
    )
    monkeypatch.setattr(
        migration,
        "_collect_mk8s_status",
        lambda **_kwargs: migration.SoperatorMigrationStatusSignal(
            "MK8s Node Groups", "serving", "large provider table"
        ),
    )
    monkeypatch.setattr(
        migration,
        "_collect_slurm_status",
        lambda **_kwargs: migration.SoperatorMigrationStatusSignal(
            "Slurm Workers", "serving", "workers ready"
        ),
    )
    monkeypatch.setattr(
        migration,
        "_collect_soperator_status",
        lambda **_kwargs: migration.SoperatorMigrationStatusSignal(
            "Soperator", "upgrading", "handoff pending"
        ),
    )
    reporter = migration.SoperatorMigrationStatusReporter(
        emit=lambda _message: None,
        nebius_api=object(),  # type: ignore[arg-type]
        command_runner=lambda *_args, **_kwargs: pytest.fail("collectors are mocked"),
        kube_context="external-context",
        checkpoint={},
        payload={},
        source_report={},
        target_ref="external-cluster",
        phase_ids=(migration.POPULATE_JAIL_REFRESH_PHASE_ID,),
        poll_interval_seconds=0,
    )

    snapshot = reporter.set_phase(migration.POPULATE_JAIL_REFRESH_PHASE_ID)

    assert snapshot is not None
    assert snapshot.signals[0].name == "Jail Upgrade"
    assert snapshot.summary.index("Jail Upgrade upgrading") < snapshot.summary.index(
        "MK8s Node Groups serving"
    )


