def test_live_home_mount_checks_fall_back_to_deployed_values_for_archived_contracts(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    deployed_values = {
        "jailPersistentMounts": [
            {"mountPath": "/home", "localPath": "/mnt/jail/home"},
        ],
        "nodesets": [{"name": "worker"}],
    }
    observed: list[Mapping[str, Any]] = []

    monkeypatch.setattr(
        migration,
        "_target_soperator_helm_stored_values",
        lambda **_kwargs: deployed_values,
    )
    monkeypatch.setattr(
        migration,
        "_effective_target_soperator_helm_values",
        lambda values: dict(values),
    )
    monkeypatch.setattr(migration, "_target_home_probe_pods", lambda **_kwargs: ())

    def login_checks(**kwargs: Any) -> tuple[Mapping[str, str], ...]:
        observed.append(kwargs["values"])
        return ()

    def worker_checks(**kwargs: Any) -> tuple[Mapping[str, str], ...]:
        observed.append(kwargs["values"])
        return ()

    monkeypatch.setattr(migration, "_login_home_mount_probe_checks", login_checks)
    monkeypatch.setattr(migration, "_worker_home_mount_probe_checks", worker_checks)

    checks = migration._live_home_mount_probe_checks(  # noqa: SLF001
        kube_context="external-context",
        command_runner=lambda args, **_kwargs: SoperatorMigrationCommandResult(
            tuple(str(item) for item in args), 0, "", ""
        ),
        values={"nodesets": [{"name": "worker"}]},
        target_ref="external-cluster",
    )

    assert checks == ()
    assert observed == [deployed_values, deployed_values]


def test_home_mount_probe_accepts_configured_volume_claim_template() -> None:
    pod = {
        "metadata": {
            "name": "login-0",
            "ownerReferences": [
                {
                    "apiVersion": "apps.kruise.io/v1beta1",
                    "kind": "StatefulSet",
                    "name": "login",
                    "controller": True,
                    "uid": "login-workload-uid",
                }
            ],
        },
        "spec": {
            "containers": [
                {
                    "name": "sshd",
                    "volumeMounts": [
                        {
                            "name": "customer-home",
                            "mountPath": "/mnt/jail.upper/home",
                        }
                    ],
                }
            ],
            "volumes": [
                {
                    "name": "customer-home",
                    "persistentVolumeClaim": {"claimName": "customer-home-login-0"},
                }
            ],
        },
    }

    def runner(
        args: Sequence[str],
        **_kwargs: Any,
    ) -> SoperatorMigrationCommandResult:
        command = tuple(str(item) for item in args)
        if "pvc" in command:
            payload = {
                "items": [
                    {
                        "metadata": {"name": "customer-home-login-0"},
                        "spec": {"accessModes": ["ReadWriteOnce"]},
                        "status": {"phase": "Bound"},
                    }
                ]
            }
        elif "statefulsets,statefulsets.apps.kruise.io" in command:
            payload = {
                "items": [
                    {
                        "apiVersion": "apps.kruise.io/v1beta1",
                        "kind": "StatefulSet",
                        "metadata": {
                            "name": "login",
                            "uid": "login-workload-uid",
                        },
                        "spec": {
                            "volumeClaimTemplates": [
                                {
                                    "metadata": {"name": "customer-home"},
                                    "spec": {"accessModes": ["ReadWriteOnce"]},
                                }
                            ]
                        },
                    }
                ]
            }
        else:
            payload = {"items": [pod]}
        return SoperatorMigrationCommandResult(
            command,
            0,
            json.dumps(payload),
            "",
        )

    configured = migration._configured_home_volume_is_mounted(  # noqa: SLF001
        command_runner=runner,
        kube_context="external-context",
        pod=pod,
        container_name="sshd",
        contracts=(
            {
                "name": "customer-home",
                "volumeClaimTemplateSpec": {"accessModes": ["ReadWriteOnce"]},
            },
        ),
    )
    check = migration._home_mount_probe_check(  # noqa: SLF001
        "/home login pod mount",
        SoperatorMigrationCommandResult(
            ("findmnt",),
            0,
            _home_mount_probe_output("/dev/storage-device", fstype="ext4"),
            "",
        ),
        expected_sources=(),
        configured_volume_mounted=configured,
    )

    assert configured is True
    assert check["status"] == "passed"


