def _mock_target_helm_apply_proof(
    monkeypatch: pytest.MonkeyPatch,
    *,
    events: list[str] | None = None,
) -> None:
    monkeypatch.setattr(
        migration,
        "_verify_target_worker_replacement_node_groups",
        lambda **_kwargs: [],
    )
    monkeypatch.setattr(
        migration,
        "_target_values_gated_by_controller_bridge",
        lambda *, values, **_kwargs: values,
    )
    monkeypatch.setattr(
        migration,
        "_handoff_controller_bridge_to_target_singleton",
        lambda **_kwargs: [],
    )
    monkeypatch.setattr(
        migration,
        "_upgrade_controller_bridge_to_target_version",
        lambda **_kwargs: [],
    )
    monkeypatch.setattr(
        migration,
        "_ensure_safe_fresh_target_helm_ordering",
        lambda **_kwargs: [],
    )
    monkeypatch.setattr(
        migration,
        "_verify_login_session_gate_hold_after_helm",
        lambda **_kwargs: [],
    )
    monkeypatch.setattr(
        migration,
        "_verify_source_reconciliation_fence_after_target_helm",
        lambda **_kwargs: [],
    )

    def checkpoint_intent(**kwargs: Any) -> list[str]:
        phase = kwargs["phase"]
        phase["target_values_apply_started_at"] = "2026-07-12T00:00:00Z"
        phase["target_handoff_values_apply_intent"] = {
            "schema": migration._TARGET_HELM_APPLY_INTENT_SCHEMA,  # noqa: SLF001
            "status": "prepared",
        }
        writer = kwargs.get("checkpoint_writer")
        if callable(writer):
            writer()
        return ["helm intent"]

    def checkpoint_proof(**kwargs: Any) -> list[str]:
        phase = kwargs["phase"]
        phase["target_handoff_values_revision"] = migration._ROLLING_COMPUTE_VALUES_REVISION  # noqa: SLF001
        phase["target_handoff_values_applied_at"] = "2026-07-12T00:00:00Z"
        phase["target_handoff_values_proof"] = {
            "schema": migration._TARGET_HELM_APPLY_PROOF_SCHEMA,  # noqa: SLF001
            "status": "verified",
        }
        phase["target_handoff_values_semantic_drift"] = {
            "schema": migration._TARGET_HELM_SEMANTIC_DRIFT_SCHEMA,  # noqa: SLF001
            "status": "compatible",
        }
        writer = kwargs.get("checkpoint_writer")
        if callable(writer):
            writer()
        if events is not None:
            events.append("helm-proof")
        return ["helm proof"]

    monkeypatch.setattr(
        migration,
        "_checkpoint_target_soperator_helm_apply_intent",
        checkpoint_intent,
    )
    monkeypatch.setattr(
        migration,
        "_checkpoint_proven_target_soperator_helm_apply",
        checkpoint_proof,
    )


