def test_reconcile_slurm_worker_runtime_identity_uses_current_worker_pods() -> None:
    calls: list[tuple[str, ...]] = []

    def runner(
        args: Sequence[str],
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorMigrationCommandResult:
        del input_text, timeout_seconds, check
        command = tuple(str(item) for item in args)
        calls.append(command)
        if command[:7] == (
            "kubectl",
            "--context",
            "external-context",
            "-n",
            "soperator",
            "get",
            "pods",
        ):
            return SoperatorMigrationCommandResult(
                command,
                0,
                json.dumps(
                    {
                        "items": [
                            {
                                "metadata": {
                                    "name": "worker-0",
                                    "labels": {"slurm.nebius.ai/worker": "true"},
                                },
                                "spec": {"nodeName": "computeinstance-new-0"},
                                "status": {"phase": "Running"},
                            },
                            {
                                "metadata": {
                                    "name": "worker-1",
                                    "labels": {"slurm.nebius.ai/nodeset": "worker"},
                                },
                                "spec": {"nodeName": "computeinstance-new-1"},
                                "status": {"phase": "Running"},
                            },
                            {
                                "metadata": {
                                    "name": "login-0",
                                    "labels": {"app.kubernetes.io/component": "login"},
                                },
                                "spec": {"nodeName": "computeinstance-login"},
                                "status": {"phase": "Running"},
                            },
                        ]
                    }
                ),
                "",
            )
        if command[:7] == (
            "kubectl",
            "--context",
            "external-context",
            "-n",
            "soperator",
            "exec",
            "controller-0",
        ):
            script = command[-1]
            assert "expected_instance=computeinstance-new-0" in script
            assert "expected_instance=computeinstance-new-1" in script
            assert "computeinstance-login" not in script
            assert 'scontrol update NodeName="${node}" InstanceId="${expected_instance}"' in script
            assert 'scontrol update NodeName="${node}" NodeAddr="${expected_addr}"' in script
            assert "State=RESUME" not in script
            assert "resume_nodes" not in script
            assert "state_lower" not in script
            return SoperatorMigrationCommandResult(
                command,
                0,
                "worker-0 InstanceId computeinstance-old-0 -> computeinstance-new-0\n",
                "",
            )
        return SoperatorMigrationCommandResult(command, 0, "{}", "")

    lines = migration._reconcile_slurm_worker_runtime_identity(
        command_runner=runner,
        kube_context="external-context",
        target_ref="external-cluster",
    )

    assert lines == ["worker-0 InstanceId computeinstance-old-0 -> computeinstance-new-0"]
    assert len(calls) == 2


def test_in_place_worker_runtime_identity_accepts_only_verified_typed_gres_rollover(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    address = "worker-0.cluster-nodeset-svc.soperator.svc.cluster.local"
    previous = {
        "worker-0": {
            "pod_uid": "old-pod-uid",
            "instance_id": "computeinstance-0",
            "node_addr": address,
        }
    }
    current = {
        "worker-0": {
            "pod_uid": "new-pod-uid",
            "instance_id": "computeinstance-0",
            "node_addr": address,
        }
    }
    checkpoint = {
        "phase_state": {
            "populate-jail-refresh": {
                "gpu_typed_gres_worker_rollover": {
                    "schema": migration._GPU_TYPED_GRES_WORKER_ROLLOVER_SCHEMA,  # noqa: SLF001
                    "status": "verified",
                    "verified_at": "2026-07-21T05:53:18Z",
                    "old_pods": {
                        "worker-0": {
                            "uid": "old-pod-uid",
                            "node": "computeinstance-0",
                            "nodeset": "worker",
                            "statefulset_uid": "worker-sts-uid",
                        }
                    },
                    "replacement_pods": {
                        "worker-0": {
                            "uid": "new-pod-uid",
                            "node": "computeinstance-0",
                            "nodeset": "worker",
                            "statefulset_uid": "worker-sts-uid",
                        }
                    },
                }
            }
        }
    }
    phase = {
        "pre_rollout_worker_runtime_identity": {
            "schema": "nebius-cxcli/in-place-worker-runtime-identity-v1",
            "status": "verified",
            "bindings": previous,
            "bindings_fingerprint": migration._fingerprint(previous),  # noqa: SLF001
            "intent_at": "2026-07-21T05:00:00Z",
        }
    }
    monkeypatch.setattr(
        migration,
        "_target_worker_pod_runtime_bindings",
        lambda **_kwargs: current,
    )
    monkeypatch.setattr(
        migration,
        "_reconcile_slurm_worker_runtime_identity",
        lambda **_kwargs: [],
    )
    monkeypatch.setattr(
        migration,
        "_slurm_worker_runtime_identity_snapshot",
        lambda **_kwargs: {
            "worker-0": {
                "node_addr": address,
                "instance_id": "computeinstance-0",
                "state": "IDLE",
            }
        },
    )

    migration._ensure_in_place_slurm_worker_runtime_identity(  # noqa: SLF001
        checkpoint=checkpoint,
        phase=phase,
        command_runner=_FakeCommandRunner(),
        kube_context="external-context",
        target_ref="cluster",
        checkpoint_writer=lambda: None,
    )

    journal = phase["pre_rollout_worker_runtime_identity"]
    assert journal["bindings"] == current
    assert journal["bindings_history"][0]["boundary"] == "gpu-typed-gres-worker-rollover"

    tampered = copy.deepcopy(checkpoint)
    tampered["phase_state"]["populate-jail-refresh"]["gpu_typed_gres_worker_rollover"][
        "replacement_pods"
    ]["worker-0"]["statefulset_uid"] = "other-sts-uid"
    phase["pre_rollout_worker_runtime_identity"] = {
        "bindings": previous,
        "bindings_fingerprint": migration._fingerprint(previous),  # noqa: SLF001
    }
    with pytest.raises(RuntimeError, match="worker Pod identities changed"):
        migration._ensure_in_place_slurm_worker_runtime_identity(  # noqa: SLF001
            checkpoint=tampered,
            phase=phase,
            command_runner=_FakeCommandRunner(),
            kube_context="external-context",
            target_ref="cluster",
            checkpoint_writer=lambda: None,
        )


